<h2 class="kt-adv-heading7_ecc117-f0 wp-block-kadence-advancedheading vf-t-h2-sm" data-kb-block="kb-adv-heading7_ecc117-f0">Building the form</h2>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_8c5984-70","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-t-17 vf-mt-4"} -->
<p class="kt-adv-heading7_8c5984-70 wp-block-kadence-advancedheading vf-t-17 vf-mt-4" data-kb-block="kb-adv-heading7_8c5984-70">Contact Form 7 builds forms in a text editor. You write bracketed tags for each field and lay out the rest in HTML. It is quick once you know it, and it gives developers precise control, but it has a learning curve for everyone else.</p>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_b4121e-23","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-t-17 vf-mt-4"} -->
<p class="kt-adv-heading7_b4121e-23 wp-block-kadence-advancedheading vf-t-17 vf-mt-4" data-kb-block="kb-adv-heading7_b4121e-23">VuloForm uses a drag-and-drop builder. You add fields from a palette, reorder them by dragging (or with the keyboard), set labels and rules in an inspector, and preview the form exactly as visitors see it. Changes save as a draft until you hit Publish.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/column {"borderWidth":["","","",""],"uniqueID":"7_c602b1-aa","kbVersion":2,"className":"vf-reveal"} -->
<div class="wp-block-kadence-column kadence-column7_c602b1-aa vf-reveal"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"uniqueID":"7_c089eb-78","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"className":"vf-t-h2-sm"} -->
<h2 class="kt-adv-heading7_c089eb-78 wp-block-kadence-advancedheading vf-t-h2-sm" data-kb-block="kb-adv-heading7_c089eb-78">What happens to submissions</h2>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_858c2d-28","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-t-17 vf-mt-4"} -->
<p class="kt-adv-heading7_858c2d-28 wp-block-kadence-advancedheading vf-t-17 vf-mt-4" data-kb-block="kb-adv-heading7_858c2d-28">By default, Contact Form 7 emails each submission and does not keep it in your WordPress database. If the email is filtered as spam or your mail setup fails, the message is gone unless you add a separate plugin to store entries.</p>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_a90f95-f0","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-t-17 vf-mt-4"} -->
<p class="kt-adv-heading7_a90f95-f0 wp-block-kadence-advancedheading vf-t-17 vf-mt-4" data-kb-block="kb-adv-heading7_a90f95-f0">VuloForm saves every submission in your own WordPress database. You can search and filter by status and date, mark entries as read, new or spam, export to CSV, and optionally auto-delete old entries after a set number of days. Email notifications are in addition to that, not instead of it.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/column {"borderWidth":["","","",""],"uniqueID":"7_64b973-71","kbVersion":2,"className":"vf-reveal"} -->
