<h2 class="kt-adv-heading7_2a7019-90 wp-block-kadence-advancedheading vf-t-h2-sm" data-kb-block="kb-adv-heading7_2a7019-90">Logic, steps and calculations</h2>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_d8792f-69","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-t-17 vf-mt-4"} -->
<p class="kt-adv-heading7_d8792f-69 wp-block-kadence-advancedheading vf-t-17 vf-mt-4" data-kb-block="kb-adv-heading7_d8792f-69">In our October 2026 check, Contact Form 7 had no built-in conditional logic or multi-step forms and no calculations; those typically come from third-party add-ons, which you have to find, vet and keep updated.</p>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_7ab505-9e","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-t-17 vf-mt-4"} -->
<p class="kt-adv-heading7_7ab505-9e wp-block-kadence-advancedheading vf-t-17 vf-mt-4" data-kb-block="kb-adv-heading7_7ab505-9e">All three ship inside the VuloForm free plugin. Conditional rules and calculated values are also checked again on your server, so a field hidden by its rules is never stored and a required field cannot be skipped by switching off JavaScript.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/column {"borderWidth":["","","",""],"uniqueID":"7_ea9f78-d0","kbVersion":2,"className":"vf-reveal"} -->
<div class="wp-block-kadence-column kadence-column7_ea9f78-d0 vf-reveal"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"uniqueID":"7_a1442a-32","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"className":"vf-t-h2-sm"} -->
<h2 class="kt-adv-heading7_a1442a-32 wp-block-kadence-advancedheading vf-t-h2-sm" data-kb-block="kb-adv-heading7_a1442a-32">Spam and privacy</h2>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_6a456f-8f","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-t-17 vf-mt-4"} -->
<p class="kt-adv-heading7_6a456f-8f wp-block-kadence-advancedheading vf-t-17 vf-mt-4" data-kb-block="kb-adv-heading7_6a456f-8f">Contact Form 7 can be paired with reCAPTCHA and similar services, which means loading a third party's script and sharing visitor data with it.</p>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_3d4860-7c","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-t-17 vf-mt-4"} -->
<p class="kt-adv-heading7_3d4860-7c wp-block-kadence-advancedheading vf-t-17 vf-mt-4" data-kb-block="kb-adv-heading7_3d4860-7c">VuloForm uses a hidden trap field, a minimum fill time and a per-visitor rate limit, with no CAPTCHA and no third party. It makes no external connections by itself, and visitor IP addresses are not stored unless you switch that on.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/column {"borderWidth":["","","",""],"uniqueID":"7_e89fd4-bd","kbVersion":2,"className":"vf-reveal"} -->
<div class="wp-block-kadence-column kadence-column7_e89fd4-bd vf-reveal"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"uniqueID":"7_e3ae57-56","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"className":"vf-t-h2-sm"} -->
<h2 class="kt-adv-heading7_e3ae57-56 wp-block-kadence-advancedheading vf-t-h2-sm" data-kb-block="kb-adv-heading7_e3ae57-56">Where Contact Form 7 is stronger</h2>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_61adb2-14","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-t-17 vf-mt-4"} -->
<p class="kt-adv-heading7_61adb2-14 wp-block-kadence-advancedheading vf-t-17 vf-mt-4" data-kb-block="kb-adv-heading7_61adb2-14">Contact Form 7 has years of releases, a very large install base and a big ecosystem of tutorials and add-ons. VuloForm is at version 1.0 and has none of that history. If your team already knows Contact Form 7 well and your needs are simple, switching is optional rather than urgent.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_721098-47","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"className":"vf-t-h2-sm vf-mt-16 vf-mb-5"} -->
<h2 class="kt-adv-heading7_721098-47 wp-block-kadence-advancedheading vf-t-h2-sm vf-mt-16 vf-mb-5" data-kb-block="kb-adv-heading7_721098-47">How the cost compares across all plugins</h2>
<!-- /wp:kadence/advancedheading -->

<!-- wp:vuloform/graphic {"name":"cost-chart"} /-->

<!-- wp:kadence/column {"borderWidth":["","","",""],"uniqueID":"7_b66a8b-fd","kbVersion":2,"className":"vf-w-3xl vf-mt-16"} -->
