<h2 class="kt-adv-heading7_3c340f-9f wp-block-kadence-advancedheading vf-t-h2-sm" data-kb-block="kb-adv-heading7_3c340f-9f">Frequently asked questions</h2>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"level":3,"uniqueID":"7_06f460-a4","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"className":"vf-t-bold vf-mt-6"} -->
<h3 class="kt-adv-heading7_06f460-a4 wp-block-kadence-advancedheading vf-t-bold vf-mt-6" data-kb-block="kb-adv-heading7_06f460-a4">Does Contact Form 7 save submissions?</h3>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_0a5fe5-6b","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-t-body vf-lh-normal vf-mt-1h"} -->
<p class="kt-adv-heading7_0a5fe5-6b wp-block-kadence-advancedheading vf-t-body vf-lh-normal vf-mt-1h" data-kb-block="kb-adv-heading7_0a5fe5-6b">Not by default. It emails them. Storing entries typically needs an additional plugin.</p>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"level":3,"uniqueID":"7_050907-67","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"className":"vf-t-bold vf-mt-6"} -->
<h3 class="kt-adv-heading7_050907-67 wp-block-kadence-advancedheading vf-t-bold vf-mt-6" data-kb-block="kb-adv-heading7_050907-67">Is VuloForm a good Contact Form 7 alternative?</h3>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_a2173f-8c","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-t-body vf-lh-normal vf-mt-1h"} -->
<p class="kt-adv-heading7_a2173f-8c wp-block-kadence-advancedheading vf-t-body vf-lh-normal vf-mt-1h" data-kb-block="kb-adv-heading7_a2173f-8c">If you want a visual builder and a submissions inbox without leaving the free tier, yes. If you only need a basic emailed contact form and prefer markup, Contact Form 7 remains a fair choice.</p>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"level":3,"uniqueID":"7_20ec21-a0","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"className":"vf-t-bold vf-mt-6"} -->
<h3 class="kt-adv-heading7_20ec21-a0 wp-block-kadence-advancedheading vf-t-bold vf-mt-6" data-kb-block="kb-adv-heading7_20ec21-a0">Can I move my Contact Form 7 forms to VuloForm?</h3>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_83130f-3b","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-t-body vf-lh-normal vf-mt-1h"} -->
<p class="kt-adv-heading7_83130f-3b wp-block-kadence-advancedheading vf-t-body vf-lh-normal vf-mt-1h" data-kb-block="kb-adv-heading7_83130f-3b">Rebuild them in the VuloForm builder; most contact forms take a few minutes using a template. Keep Contact Form 7 active until the new form is live and tested, then deactivate it.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->

